package io.github.dream07code.innovationspace.scoring; import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)@EnableConfigurationProperties(ScoringProperties.class)public class ScoringConfiguration{@Bean MockReportScoringProvider mockReportScoringProvider(){return new MockReportScoringProvider();}@Bean ScoringProviderRegistry scoringProviderRegistry(ScoringProperties p,java.util.List<ReportScoringProvider> providers){return new ScoringProviderRegistry(p,providers);}}
